{
  "findings": [
    {
      "title": "Sample size inconsistency: total 137 vs 164",
      "page": 21,
      "quote": "Approximately 137 adult patients (53 in Group 1 and 84 in Group 2) are expected to be enrolled.",
      "severity": "critical"
    },
    {
      "title": "Sample size inconsistency: total 164 vs 137",
      "page": 23,
      "quote": "and 84 patients for Group 2, for a total of 164 patients.",
      "severity": "critical"
    },
    {
      "title": "Sample size inconsistency: Group 1 50 vs 53",
      "page": 23,
      "quote": "For Group 1, 50 patients are required to provide at least 95% power to reject a null hypothesis of an ORR of 15% at a 2-sided significance level of 5% if the true ORR is 34%.",
      "severity": "major"
    },
    {
      "title": "Sample size inconsistency: Group 2 80 vs 84",
      "page": 23,
      "quote": "For Group 2, 80 patients are required to provide at least 95% power to reject a null hypothesis of an ORR of 20% at a 2-sided significance level of 5% if the true ORR is 35%.",
      "severity": "major"
    },
    {
      "title": "Inconsistent null hypothesis for Group 2: 20% vs 15%",
      "page": 23,
      "quote": "The non-clinically meaningful ORR of 20% for Group 2 will be excluded using the lower limit of 95% CI if the observed ORR is 30.0% or more; ie, the ORR for Group 2 is significantly different from 20%.",
      "severity": "major"
    },
    {
      "title": "Inconsistent null hypothesis for Group 1: 15% vs 20%",
      "page": 23,
      "quote": "The non-clinically meaningful ORR of 15% for Group 1 will be excluded using the lower limit of 2-sided 95% confidence interval (CI) if the observed ORR is 28.0% or more; ie, the ORR for Group 1 is significantly different from 15%.",
      "severity": "major"
    },
    {
      "title": "Inconsistent primary endpoint criteria: RECIST/WHO vs clinical/composite",
      "page": 23,
      "quote": "The primary endpoint for efficacy analyses is the ORR as determined by RECIST version 1.1 for visceral lesions or by modified WHO criteria for skin lesions or by the composite response criteria for patients with both visceral and skin lesions.",
      "severity": "major"
    },
    {
      "title": "Inconsistent primary endpoint criteria: clinical vs RECIST",
      "page": 22,
      "quote": "For patients in Group 1 (metastatic BCC), Response Evaluation Criteria in Solid Tumors (RECIST) version 1.1 will be used to determine ORR. Clinical response criteria may be used for patients with externally visible target lesions if all metastatic lesions are not measurable by RECIST (as may occur in patients with bone-only metastases).",
      "severity": "major"
    },
    {
      "title": "Inconsistent primary endpoint criteria: clinical vs composite",
      "page": 22,
      "quote": "For patients in Group 2 (unresectable locally advanced BCC), clinical criteria will be used to determine ORR. Composite response criteria will be used for patients with lesions that are measurable by both clinical response criteria and RECIST 1.1.",
      "severity": "major"
    },
    {
      "title": "Inconsistent treatment duration: 93 weeks vs 5 cycles of 9 weeks + 4 cycles of 12 weeks",
      "page": 21,
      "quote": "Tumor assessments will be made at the end of each treatment cycle, 5 treatment cycles of 9 weeks followed by 4 treatment cycles of 12 weeks).",
      "severity": "major"
    },
    {
      "title": "Inconsistent treatment duration: 93 weeks vs 5 cycles of 9 weeks + 4 cycles of 12 weeks",
      "page": 21,
      "quote": "A patient will receive treatment until the 93-week treatment period is complete, or until disease progression (PD), unacceptable toxicity, withdrawal of consent, or confirmed CR.",
      "severity": "major"
    },
    {
      "title": "Inconsistent treatment duration: 93 weeks vs 5 cycles of 9 weeks + 4 cycles of 12 weeks",
      "page": 21,
      "quote": "Cemiplimab at 350 mg administered IV over 30 minutes (± 10 minutes) Q3W for up to 93 weeks",
      "severity": "major"
    }
  ]
}
